r/exact edition cover binding, readable published front"}],"work_id":2232,"language":"nl","bound_author_id":419,"text":"Henry Turner heeft moeite zijn studie te combineren met zijn nieuwe verantwoordelijkheid als aanvoerder van het ijshockeyteam. Halle Jacobs biedt hem hulp aan, terwijl zij zelf vastloopt bij het schrijven van een boek. Hun samenwerking levert beiden iets op dat niet in een studieplanning past. Het derde Maple Hills-boek volgt hoe vriendschap en onderlinge verwachtingen veranderen wanneer praktische afspraken ruimte maken voor persoonlijke gevoelens.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1927414/dagdroom.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789000391516","key":{"isbn_13":"9789000391516"},"before":null,"after":{"work_id":2531,"title":"Heartstopper","isbn_13":"9789000391516","isbn_10":"9000391512","language":"nld","publisher":"Uitgeverij Unieboek | Het Spectrum"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789000391516","key":{"edition_id":"@edition:9789000391516"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/2066700/heartstopper-deel-6.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.lannoo.com/nl-nl/literatuur-romans/heartstopper-9789000391516","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000771427_Heartstopper_Deel_6_0_0.jpg","checkedAt":"2026-10-31T23:13:01.71Z","sha256":"67aa85b17f35c53148ab3b78ad8597dacb6920dd008eae48a2dd798c9358c17c","bytes":700479,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789000391516","work_id":2531,"bound_author_id":302,"bound_title"