literatuur-romans/de-wapens-van-het-licht-9789049205928","checkedAt":"2026-10-31","fact":"Retained reviewed prior identity/edition/content evidence"},{"url":"https://www.vanderveldeboeken.nl/BookApi/GetSample?guid=e82e731f-cdee-4475-99d3-f220d3cf9ca2","checkedAt":"2026-10-31","fact":"Retained reviewed prior identity/edition/content evidence"},{"url":"https://openlibrary.org/books/OL46565140M","checkedAt":"2026-10-31","fact":"Retained reviewed prior identity/edition/content evidence"},{"url":"https://metadata.isbn.nl/ie_fcache/0000538304_De_wapens_van_het_licht_0_0.jpg","checkedAt":"2026-10-31","sha256":"9d7e4a8dc30e8cd8c1466deaf4430662e3225399ebe5f940d47f87696938dbb8","bytes":958622,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":2532,"language":"nl","bound_author_id":358,"text":"Aan het einde van de achttiende eeuw verandert de industrie het leven in Kingsbridge. Spinster Sal Clitheroe probeert haar werk en de toekomst van haar zoon Kit veilig te stellen. Samen met wever David Shoveller zoekt zij houvast terwijl nieuwe machines en harde arbeidsverhoudingen de stad veranderen. Tegelijk groeit de dreiging van oorlog op het Europese vasteland, waardoor persoonlijke zorgen en grote geschiedenis elkaar raken.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1669951/de-wapens-van-het-licht.html","provenance":"original_source_reviewed_summary"}}]'::jsonb) loop i:=i+1;select value into r from jsonb_array_elements(receipt->'rows') where (value->>'seq')::integer=i;if r is null or (select count(*) from jsonb_array_elements(receipt->'rows') where (value->>'seq')::integer=i)<>1 or r->>'relation' is distinct from p->>'relation' or r->'before_row' is distinct from p->'before' then raise exception 'Reviewed receipt manifest mismatch';end if;k:=p->'key';e:=p->'after';for v in select * from jsonb_each(e) loop if jsonb_typeof(v.value)='string' and left(v.value#>>'{}',1)='@' then e:=jsonb_set(e,array[v.key],ids->substring(v.value#>>'{}',2));end if;end loop;for v in select * from jsonb_each(k) loop if jsonb_typeof(v.value)='string' and left(v.value#>>'{}',1)='@' then k:=jsonb_set(k,array[v.key],ids->substring(v.value#>>'{}',2));end if;end loop;execute format('select coalesce(jsonb_object_agg(x.key,x.value),''{}''::jsonb) from jsonb_each(to_jsonb(jsonb_populate_record(null::public.%I,$1))) x where $1 ? x.key',p->>'relation') into e using e;if r->'key' is distinct from k or not coalesce((r->'after_row')@>e,false) then raise exception 'Reviewed receipt values mismatch';end if;if r->'after_row' ? 'id' then ids:=jsonb_set(ids,array[p->>'ref'],r->'after_row'->'id');end if;end loop;end;$reviewed_receipt$;
do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'qvplwejffhjvxaypmjut' or receipt->>'batch' is distinct from 'nl-cohort003-04-20261101' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>33 then raise exception 'Exact first committed receipt required';end if;
 for r in select value from jsonb_array_elements(receipt->'rows') order by (value->>'seq')::integer desc loop
  if r->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed receipt relation';end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',r->>'relation') into actual using r->'key';
  if actual is null and r->'before_row'='null'::jsonb then continue;end if;
  if actual is not distinct from r->'before_row' then continue;end if;
  if actual is distinct from r->'after_row' then raise exception 'Later legitimate change; recovery refused';end if;
  if r->'before_row'='null'::jsonb then
   for dep in select ns.nspname,c.relname,string_agg(format('(to_jsonb(child)->%L)=($1->%L)',ca.attname,pa.attname),' and ' order by k.ord) predicate
    from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace
    cross join lateral unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord)
    join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey
    where f.contype='f' and f.confrelid=to_regclass('public.'||(r->>'relation')) group by f.oid,ns.nspname,c.relname
   loop
    execute format('select count(*) from %I.%I child where %s',dep.nspname,dep.relname,dep.predicate) into n using r->'after_row';
    if n>0 then raise exception 'Later dependency in %.%; recovery refused',dep.nspname,dep.relname;end if;
   end loop;
   execute format('delete from public.%I t where to_jsonb(t) @> $1',r->>'relation') using r->'key';
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),',') into cols from jsonb_each(r->'before_row') where value is distinct from r->'after_row'->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2',r->>'relation',cols) using r->'before_row',r->'key';
  end if;
 end loop;
end;$undo$;commit;
